import org.junit.jupiter.api.Test;

class LmdbCrossInputFilterPlacementTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:predicate");
	private static final List<Statement> STATEMENTS = List.of(
			VF.createStatement(VF.createIRI("urn:subject:one"), PREDICATE, VF.createLiteral("match")),
			VF.createStatement(VF.createIRI("urn:subject:two"), PREDICATE, VF.createLiteral("match")));

	@Test
	void keepsCrossInputFilterAboveJoinSupplyingBothBindings() {
		StatementPattern left = statementPattern("value");
		BindingSetAssignment right = values("right", "right-value");
		DeferredFilter filter = new DeferredFilter(
				new Compare(new Var("value"), new Var("right"), Compare.CompareOp.EQ),
				Set.of("value", "right"), 1, 0, null, Set.of(),
				new EvaluationStatistics.FilterPassEstimate(-1.0d,
						EvaluationStatistics.FilterPassEstimate.Source.UNKNOWN));
		LmdbDeferredFilterPlacer placer = new LmdbDeferredFilterPlacer((tupleExpr, ignored) -> tupleExpr,
				Join::new, (root, filters, placement) -> {
					TupleExpr result = root;
					for (DeferredFilter deferredFilter : filters) {
						result = new Filter(result, deferredFilter.condition.clone());
					}
					return result;
				});

		TupleExpr root = placer.buildSegmentRoot(new ArrayDeque<>(List.of(left, right)), List.of(filter), Set.of());

		Filter placedFilter = assertInstanceOf(Filter.class, root);
		Join joinedOperands = assertInstanceOf(Join.class, placedFilter.getArg());
		assertSame(left, joinedOperands.getLeftArg());
		assertSame(right, joinedOperands.getRightArg());
	}

	@Test
	void evaluatesCrossInputFilterWithDuplicateAndUnboundRows() throws QueryEvaluationException {
		StatementPattern left = statementPattern("value");
		BindingSetAssignment right = valuesWithUnbound("right", "match", "match", "other", null);
		TupleExpr root = newPlacer().buildSegmentRoot(new ArrayDeque<>(List.of(left, right)),
				List.of(crossInputFilter()), Set.of());

		List<BindingSet> rows = evaluate(root);

		assertEquals(4, rows.size(), "both duplicate VALUES rows must survive the equality join");
		assertTrue(rows.stream()
				.allMatch(row -> VF.createLiteral("match").equals(row.getValue("value"))
						&& VF.createLiteral("match").equals(row.getValue("right"))));
	}

	@Test
	void sketchOptimizerPreservesNestedCrossInputFilterResults() throws QueryEvaluationException {
		StatementPattern leftValues = statementPattern("value");
		BindingSetAssignment marker = values("marker", "m");
		Join nestedLeft = new Join(leftValues, marker);
		nestedLeft.setVariableScopeChange(true);
		BindingSetAssignment right = valuesWithUnbound("right", "match", "match", "other", null);
		QueryRoot root = new QueryRoot(new Filter(new Join(nestedLeft, right), crossInputFilter().condition.clone()));

		new LmdbSketchJoinOptimizer(new EvaluationStatistics(), false).optimize(root, null,
				EmptyBindingSet.getInstance());
		List<BindingSet> rows = evaluate(root.getArg());

		assertEquals(4, rows.size(), "nested joins must retain duplicate matches and discard UNDEF rows");
		assertTrue(rows.stream()
				.allMatch(row -> VF.createLiteral("match").equals(row.getValue("value"))
						&& VF.createLiteral("match").equals(row.getValue("right"))));
	}

	@Test
	void sketchOptimizerPreservesCrossInputFilterWithInitialBinding() throws QueryEvaluationException {
		StatementPattern left = statementPattern("value");
		BindingSetAssignment right = valuesWithUnbound("right", "match", "match", "other", null);
		QueryRoot root = new QueryRoot(new Filter(new Join(left, right), crossInputFilter().condition.clone()));
		MapBindingSet initialBindings = new MapBindingSet(1);
		initialBindings.addBinding("value", VF.createLiteral("match"));

		new LmdbSketchJoinOptimizer(new EvaluationStatistics(), false).optimize(root, null, initialBindings);
		List<BindingSet> rows = evaluate(root.getArg(), initialBindings);

		assertEquals(4, rows.size(), "initial bindings must preserve duplicate compatible results");
		assertTrue(rows.stream()
				.allMatch(row -> VF.createLiteral("match").equals(row.getValue("value"))
						&& VF.createLiteral("match").equals(row.getValue("right"))));
	}

	private static LmdbDeferredFilterPlacer newPlacer() {
		return new LmdbDeferredFilterPlacer((tupleExpr, ignored) -> tupleExpr, Join::new,
				(root, filters, placement) -> {
					TupleExpr result = root;
					for (DeferredFilter deferredFilter : filters) {
						result = new Filter(result, deferredFilter.condition.clone());
					}
					return result;
				});
	}

	private static DeferredFilter crossInputFilter() {
		return new DeferredFilter(new Compare(new Var("value"), new Var("right"), Compare.CompareOp.EQ),
				Set.of("value", "right"), 1, 0, null, Set.of(),
				new EvaluationStatistics.FilterPassEstimate(-1.0d,
						EvaluationStatistics.FilterPassEstimate.Source.UNKNOWN));
	}

	private static List<BindingSet> evaluate(TupleExpr root) throws QueryEvaluationException {
		return evaluate(root, EmptyBindingSet.getInstance());
	}

	private static List<BindingSet> evaluate(TupleExpr root, BindingSet initialBindings)
			throws QueryEvaluationException {
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(new TestTripleSource(), null);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = strategy.evaluate(root, initialBindings)) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private static BindingSetAssignment values(String bindingName, String value) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(bindingName));
		MapBindingSet bindingSet = new MapBindingSet(1);
		bindingSet.addBinding(bindingName, VF.createLiteral(value));
		assignment.setBindingSets(new ArrayList<>(List.of(bindingSet)));
		return assignment;
	}

	private static BindingSetAssignment valuesWithUnbound(String bindingName, String... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(bindingName));
		List<BindingSet> bindingSets = new ArrayList<>(values.length);
		for (String value : values) {
			MapBindingSet bindingSet = new MapBindingSet(1);
			if (value != null) {
				bindingSet.addBinding(bindingName, VF.createLiteral(value));
			}
			bindingSets.add(bindingSet);
		}
		assignment.setBindingSets(bindingSets);
		return assignment;
	}

	private static StatementPattern statementPattern(String valueBindingName) {
		return new StatementPattern(new Var("entity"), new Var("predicate", PREDICATE),
				new Var(valueBindingName));
	}

	private static final class TestTripleSource implements TripleSource {

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			List<Statement> matches = new ArrayList<>(STATEMENTS.size());
			for (Statement statement : STATEMENTS) {
				if ((subj == null || subj.equals(statement.getSubject()))
						&& (pred == null || pred.equals(statement.getPredicate()))
						&& (obj == null || obj.equals(statement.getObject()))) {
					matches.add(statement);
				}
			}
			return new CloseableIteratorIteration<>(matches.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
}
